set -e
curl -s --max-time 60 "https://openrouter.ai/api/v1/models?sort=top-weekly" -o /tmp/models.json
cat > /tmp/sim.cjs <<'JS'
const fs = require('fs');
const MS = require('/home/runner/work/inhouselearn/inhouselearn/model-scores.js');
const d = JSON.parse(fs.readFileSync('/tmp/models.json', 'utf8')).data;
const chat = (e) => { const a = e.architecture || {}; const i = a.input_modalities || ['text']; const o = a.output_modalities || ['text']; return i.includes('text') && o.includes('text') && !o.includes('image') && !o.includes('audio') && !e.id.startsWith('~') && !e.id.endsWith(':batch'); };
const sum = d.filter(chat).map((e) => { const b = e.benchmarks && e.benchmarks.artificial_analysis; return { id: e.id, name: e.name, intelligence: b && typeof b.intelligence_index === 'number' ? b.intelligence_index : null, coding: b && typeof b.coding_index === 'number' ? b.coding_index : null, agentic: b && typeof b.agentic_index === 'number' ? b.agentic_index : null, created: e.created }; });
const fits = MS.fits(sum);
console.log('fits', Object.entries(fits).map(([k, f]) => k + ' n=' + f.n + ' r2=' + f.r2.toFixed(3) + ' coef=' + f.coef.map((x) => x.toFixed(3)).join(',')).join(' | '));
const out = MS.estimate(sum);
let real = 0, est = 0, none = 0; const byCo = {};
out.forEach((e) => { const co = e.id.split('/')[0]; byCo[co] = byCo[co] || { real: 0, est: 0, none: 0 }; if (e.intelligence != null && !e.iqEstimated) { real++; byCo[co].real++; } else if (e.iqEstimated) { est++; byCo[co].est++; } else { none++; byCo[co].none++; } });
console.log('TOTAL', out.length, 'real', real, 'est', est, 'none', none);
console.log('by company (none>0):');
Object.entries(byCo).filter(([, v]) => v.none > 0).sort((a, b) => b[1].none - a[1].none).forEach(([k, v]) => console.log(' ', k, JSON.stringify(v)));
console.log('--- deepseek after estimate ---');
out.filter((e) => e.id.includes('deepseek')).forEach((e) => console.log(e.id, '=>', e.intelligence, e.iqEstimated ? '(est)' : '', '| coding', e.coding, 'agentic', e.agentic));
